<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Holder\TrustedClientRequirePkceAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientRequirePkceAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TrustedClientRequirePkceAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that isRequirePkce returns null on a freshly created holder.
     */
    public function testRequirePkceNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientRequirePkceAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isRequirePkceAssigned());
        $this->assertNull($holder->isRequirePkce());
    }
}
class ImplWithTrustedClientRequirePkceAttributeHolderUnitTest
{
    use TrustedClientRequirePkceAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedRequirePkceRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultRequirePkce();
    }
}
